import os, tempfile
from pathlib import Path

class MyTmp(tempfile.TemporaryDirectory):   # 外部基底が __enter__/__exit__ を持つ（木内に無い）
    def label(self): return "x"

class Runner:
    def __init__(self, cwd): self.cwd = cwd
    def __enter__(self): return self
    def __exit__(self, *exc): return False
    def run(self, cmd): os.system(cmd)

class Lock:
    def __init__(self): self.held = False
    def __enter__(self): self.held = True; return self
    def __exit__(self, *exc): self.held = False

LOCK = Lock()

